+// Flags: --allow-natives-syntax
+
+function f0(a1) {
+  let v10 = Math.max((a1 | 0) * (2 ** 52), 4294967297);
+  v10--;
+  return v10 + v10;
+}
+
+%PrepareFunctionForOptimization(f0);
+f0(0); // Addition will have AdditiveSafeInt feedback.
+%OptimizeFunctionOnNextCall(f0);
